  ["4c04b0d7df9fb4e0"] = { "Pare che i ⟦Southsea Freebooters=Filibustieri dei Mari del Sud⟧ si siano trincerati per bene sulla costa. Potrebbe mettersi male.", "." },
  ["4c0c7ae34e7cd210"] = { "Sparpagliatevi! Scoprite chi è stato. Sarà licenziato di sicuro!", "." },
  ["4c0c8872e0bf1b62"] = { "Le energie assorbite avrebbero sostenuto la magia degli Alti Nobili, permettendo a chi stava entro le mura di Eldre'Thalas di placare la sua fame di magia, infinita e crescente.\n\nPassarono migliaia di anni, e il potere necessario per tenere prigioniero Immol'thar e al tempo stesso sostenere la vita a Eldre'Thalas cominciò a cambiare. Il costo per tenere vincolato Immol'thar arrivò a superare la quantità di energia che si poteva assorbire e distribuire. Quello che un tempo era un guadagno netto divenne una perdita.", "." },
  ["4c0cfaf50f763960"] = { "Pare che mi serva altra pratica!", "." },
