  ["4c44dc2c292c9808"] = { "Sei davvero un<o/a> eroe speciale, {name}. Ti diamo il benvenuto nel mondo di Azeroth e ti offriamo uno di questi doni unici!", "." },
  ["4c4a370c2bcd2ab9"] = { "No! Non puoi sconfiggermi!", "." },
  ["4c4ce8c0f145310e"] = { "Ho una malattia. Ti prego, curami, medico.", "." },
  ["4c5b0695ba32557a"] = { "Cosa posso fare per te? No, aspetta! Cosa puoi fare tu per me?", "." },
  ["4c5fde4e1dff88da"] = { "Ah, dunque... l'hai trovato.\n\n<Mathredis indica il libro in tuo possesso.>\n\nHai raccolto i componenti necessari?\n\nLe manifestazioni elencate nel compendio, imbecille!", "." },
  ["4c603d353c7fe6da"] = { "A ⟦Razor Hill=Tranciacolle⟧ c'è un istruttore di ingegneria. Si chiama Mukdrak e di solito lo trovi in piedi vicino alla forgia.", "." },
