  ["4ce7b58dd6b49fc0"] = { "Vuoi addestrarti? Con me? Fantastico! L'unica cosa meglio che assemblare proiettili e ordigni esplosivi è condividere quel sapere con qualcun altro! Cominciamo!", "." },
