  ["4cfa9c3d0fa5972e"] = { "I progetti sono lì dentro!", "." },
  ["4cfb289952337e89"] = { "Cosa? {name}, mi hai servito bene, ma...", "." },
  ["4cff463abc608552"] = { "Ah, non c'è niente come un volo in groppa a un grifone, vero? Gli elfi della notte possono tenersi quei loro ippo... grifi, a me basta un grifone e il vento nei capelli!\n\nBene, non ti trattengo oltre: vai da Gryth Thurden sul lato est della ⟦Great Forge=Grande Forgia⟧ e lui ti metterà in viaggio.", "." },
